import type { City, Coordinate, LandPolygon, Scenario } from '../types';
import generated from './generated/world-land.json';
import cities from './generated/cities.json';
import { MANUAL_ISLANDS } from './islands';

// Land geometry is generated by scripts/prepare-map.mjs from Natural Earth v5.1.2 (public domain).
// Coordinates are [longitude, latitude]; rings are open (first point is not repeated).
// Polygons are split at ±180 by Natural Earth, so no ring crosses the antimeridian.
export const LAND_POLYGONS: LandPolygon[] = [...(generated.landPolygons as LandPolygon[]), ...MANUAL_ISLANDS];

// Impact cities are generated by scripts/prepare-map.mjs: every Natural Earth 10m populated place with
// POP_MAX >= 500,000 plus the original demonstration set (same ids, English names and coordinates).
// Populations are Natural Earth's POP_MAX estimates (metro areas, round to the thousand); largest first.
export const CITIES: City[] = cities as City[];

export const SCENARIO: Scenario = {
  id: 'world-fictional-2025-a',
  name: 'Fictional Worldwide Sandbox (2025 basis)',
  seed: 20261022,
  version: '0.8.0',
  description:
    'This is an unlimited, real-time fictional world, not a forecast or a replay of any real typhoon. Sea surface temperature, humidity, and wind background are invented for gameplay. They change with the warm water, moisture, and pressure tools the player places, and with the storms those create. Coastlines, city coordinates and city populations come from Natural Earth; the weather and the rural background population are invented. Impact totals are game measures (wind exposure of population cells times a damage rate), not casualty counts or financial loss estimates.',
  populationNote:
    'City populations are Natural Earth POP_MAX estimates (2025 basis).',
  sources: [
    {
      name: 'Natural Earth 50m land (v5.1.2)',
      url: 'https://github.com/nvkelso/natural-earth-vector/tree/v5.1.2/geojson',
      license: 'Public domain',
    },
    {
      name: 'Natural Earth 50m lakes (v5.1.2): lake outlines and names, drawn only (the simulation treats lakes as land)',
      url: 'https://github.com/nvkelso/natural-earth-vector/tree/v5.1.2/geojson',
      license: 'Public domain',
    },
    {
      name: 'Natural Earth 10m populated places (v5.1.2): city coordinates, POP_MAX populations and Korean names',
      url: 'https://github.com/nvkelso/natural-earth-vector/tree/v5.1.2/geojson',
      license: 'Public domain',
    },
    { name: 'Weather background (game demonstration values)', url: '', license: 'Project-internal fictional data' },
  ],
};

// One band per whole degree of latitude, from -90 (band 0) to 89 (band 179). Latitude 90 uses band 179.
const BAND_SOUTH = -90;
const BAND_COUNT = 180;
type Edge = [x1: number, y1: number, x2: number, y2: number];
const EDGE_BANDS: Edge[][] = Array.from({ length: BAND_COUNT }, () => []);

const bandOf = (lat: number): number => Math.min(BAND_COUNT - 1, Math.max(0, Math.floor(lat) - BAND_SOUTH));

for (const polygon of LAND_POLYGONS) {
  for (const ring of [polygon.outer, ...(polygon.holes ?? [])]) {
    for (let i = 0; i < ring.length; i++) {
      const [x1, y1] = ring[i] as Coordinate;
      const [x2, y2] = ring[(i + 1) % ring.length] as Coordinate;
      for (let band = bandOf(Math.min(y1, y2)); band <= bandOf(Math.max(y1, y2)); band++) {
        EDGE_BANDS[band].push([x1, y1, x2, y2]);
      }
    }
  }
}

// A ray cast to the east from (x, y) crosses this edge.
const crosses = (x: number, y: number, [x1, y1, x2, y2]: Edge): boolean =>
  (y1 > y) !== (y2 > y) && x < x1 + ((y - y1) * (x2 - x1)) / (y2 - y1);

// Wraps any longitude into [-180, 180) so that 181° and -179° are the same place.
export const wrapLon = (lon: number): number => ((((lon + 180) % 360) + 360) % 360) - 180;

// Even-odd ray cast across every ring, so holes and islands inside holes resolve correctly.
// Returns false for latitudes outside [-90, 90] and for NaN input.
export function isLand(lon: number, lat: number): boolean {
  if (!(lat >= -90 && lat <= 90)) return false;
  const edges = EDGE_BANDS[bandOf(lat)];
  const x = wrapLon(lon);
  let inside = false;
  for (const edge of edges) if (crosses(x, lat, edge)) inside = !inside;
  return inside;
}

/** Even-odd test against one polygon (outer ring minus holes), using the same edge crossing as isLand. */
export function inPolygon(lon: number, lat: number, polygon: LandPolygon): boolean {
  const x = wrapLon(lon);
  let inside = false;
  for (const ring of [polygon.outer, ...(polygon.holes ?? [])]) {
    for (let i = 0; i < ring.length; i++) {
      const [x1, y1] = ring[i] as Coordinate;
      const [x2, y2] = ring[(i + 1) % ring.length] as Coordinate;
      if (crosses(x, lat, [x1, y1, x2, y2])) inside = !inside;
    }
  }
  return inside;
}

// Lazy land raster for hot paths (ship routing samples a segment every few km). Each 0.1 degree cell,
// built on first use, keeps the exact ray-cast answer in a cheaper form: whether the eastward ray
// crosses an odd number of edges that lie wholly east of the cell and span its latitude slab (a
// constant for the cell), plus the few edges that touch the cell or start/end inside its slab. The
// result is the same parity isLand computes, from a handful of edges instead of the whole band.
const RASTER_CELL = 0.1;
const RASTER_COLS = Math.round(360 / RASTER_CELL), RASTER_ROWS = Math.round(180 / RASTER_CELL);
const RASTER_PAD = 1e-9;
interface RasterCell { base: boolean; edges: Edge[] }
const ALL_OCEAN: RasterCell = { base: false, edges: [] }, ALL_LAND: RasterCell = { base: true, edges: [] };
const raster: (RasterCell | undefined)[] = new Array(RASTER_COLS * RASTER_ROWS);

// Liang-Barsky: does the segment touch the rectangle?
function edgeTouches([x1, y1, x2, y2]: Edge, xMin: number, yMin: number, xMax: number, yMax: number): boolean {
  let t0 = 0, t1 = 1;
  const dx = x2 - x1, dy = y2 - y1;
  for (const [p, q] of [[-dx, x1 - xMin], [dx, xMax - x1], [-dy, y1 - yMin], [dy, yMax - y1]]) {
    if (p === 0) { if (q < 0) return false; continue; }
    const r = q / p;
    if (p < 0) { if (r > t1) return false; if (r > t0) t0 = r; } else { if (r < t0) return false; if (r < t1) t1 = r; }
  }
  return true;
}

function buildCell(col: number, row: number): RasterCell {
  const xMin = col * RASTER_CELL - 180 - RASTER_PAD, xMax = xMin + RASTER_CELL + 2 * RASTER_PAD;
  const yMin = row * RASTER_CELL - 90 - RASTER_PAD, yMax = yMin + RASTER_CELL + 2 * RASTER_PAD;
  const cell: RasterCell = { base: false, edges: [] };
  let coastal = false;
  // The padded slab may reach into a neighbouring band; an edge listed in both is taken in the first.
  const first = bandOf(yMin);
  for (let band = first; band <= bandOf(yMax); band++) {
    for (const edge of EDGE_BANDS[band]) {
      const [x1, y1, x2, y2] = edge, lo = Math.min(y1, y2), hi = Math.max(y1, y2);
      if (band > first && bandOf(lo) < band) continue;
      if (hi < yMin || lo > yMax) continue; // never crossed by a ray inside the slab
      if (edgeTouches(edge, xMin, yMin, xMax, yMax)) { coastal = true; if (lo !== hi) cell.edges.push(edge); continue; }
      if (lo === hi) continue; // a horizontal edge is never crossed by an eastward ray
      const ym = (Math.max(lo, yMin) + Math.min(hi, yMax)) / 2;
      if (x1 + ((ym - y1) * (x2 - x1)) / (y2 - y1) < xMin) continue; // wholly west: no ray from the cell reaches it
      if (lo <= yMin && hi > yMax) cell.base = !cell.base; // wholly east and spanning: crossed by every ray
      else cell.edges.push(edge);
    }
  }
  if (!coastal) { // no edge enters the cell, so one answer holds throughout: take it at the centre
    const cx = (xMin + xMax) / 2, cy = (yMin + yMax) / 2;
    for (const edge of cell.edges) if (crosses(cx, cy, edge)) cell.base = !cell.base;
    return cell.base ? ALL_LAND : ALL_OCEAN;
  }
  return cell;
}

/** Same result as isLand, from a lazily built per-cell edge subset. */
export function isLandCached(lon: number, lat: number): boolean {
  if (!(lat >= -90 && lat <= 90)) return false;
  const x = wrapLon(lon);
  const col = Math.min(RASTER_COLS - 1, Math.floor((x + 180) / RASTER_CELL));
  const row = Math.min(RASTER_ROWS - 1, Math.floor((lat + 90) / RASTER_CELL));
  const i = row * RASTER_COLS + col;
  const cell = raster[i] ?? (raster[i] = buildCell(col, row));
  let inside = cell.base;
  for (const edge of cell.edges) if (crosses(x, lat, edge)) inside = !inside;
  return inside;
}
